import{z as D,x as s,o as e,c as i,q as t,j as o,D as a,d as r,s as l,S as A}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"PD 分离的调度","description":"","frontmatter":{"title":"PD 分离的调度","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sch-pd-disaggregated.md","filePath":"llm/sch-pd-disaggregated.md","lastUpdated":1791063341000}'),n={name:"llm/sch-pd-disaggregated.md"};function d(p,E,P,c,g,h){const B=s("Mermaid");return e(),i("div",null,[E[2]||(E[2]=t('<h1 id="pd-分离的调度" tabindex="-1">PD 分离的调度 <a class="header-anchor" href="#pd-分离的调度" aria-label="Permalink to &quot;PD 分离的调度&quot;">​</a></h1><div class="epigraph"><p>拆池之后，耦合没有消失，只是换了个位置：从「同一步抢算力」变成「KV 传输与两池队列的错位」。</p><footer>—— 据 Zhong et al., OSDI 2024 与 Patel et al., Splitwise, ISCA 2024 的系统口径整理</footer></div><p><a href="/llm/sch-preemption-migration">上一课</a>写完让路的三本账；本课换一个轴：把 prefill 与 decode 拆到不同池子后，调度问题怎么重写。拆分的动机与 KV 搬运的机制主干已有（<a href="/llm/pd-disaggregation">PD 分离</a>、<a href="/llm/pd-kv-transfer">PD 分离的 KV 传输</a>）；本课只写调度器新增的决定：请求去哪个 P 实例、KV 何时送到哪个 D 实例、两池配比多少、两池之间怎么反压。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>拆开之后，调度器多出一组决定，每一个都新。<span class="marginnote">术语翻译：PD 分离就是把「读题」和「答题」拆到两批不同的卡上——prefill 负责读完整段提示（算力活），decode 负责一个字一个字往外蹦（带宽活）。两种活的硬件胃口不同，混在一张卡上会互相踩脚，拆开就能各配各的卡型与卡数。</span>第一，<strong>路由</strong>：请求进 P 池，算完首 token 后 KV 要跟着去某个 D 实例——D 的选择就是亲和问题，一旦选定，整条生成轨迹粘在那台上。第二，<strong>传输时机</strong>：KV 按层流水送出、与最后一段分块前填重叠，目标是首 token 一算完、D 侧开跑时 KV 已就位；送早了占 D 的显存，送晚了 D 干等。第三，<strong>配比</strong>：两池卡数比错了，一头排队一头空转。第四，<strong>反压</strong>：colocate 系统里本步 token 预算天然是反压；拆开后两池是两个进程，P 不知道 D 已经满——P 继续吐 KV，D 的池子被打爆，排队的是显存不是请求。</p><h3 id="配比从负载算" tabindex="-1">配比从负载算 <a class="header-anchor" href="#配比从负载算" aria-label="Permalink to &quot;配比从负载算&quot;">​</a></h3><p>稳态下两池的卡数比近似等于每请求在两阶段的服务时间之比：\\(N_P/N_D \\approx (\\bar{p}/r_P)/(\\bar{o}/r_D)\\)，其中 \\(\\bar{p}\\)、\\(\\bar{o}\\) 是平均提示与输出长度，\\(r_P\\)、\\(r_D\\) 是单卡在两阶段的实测吞吐。这是起点不是终点：TTFT 承诺紧就往 P 侧加卡，TPOT 紧就往 D 侧加。DistServe 干脆按 goodput 对两池分别搜并行与副本数；Splitwise 把异构档位配进来——prompt 用高算力卡，decode 用低功耗档，把功耗账也算进配比。</p>',7)),(e(),o(A,null,{default:a(()=>[l(B,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%EF%BC%9A%E6%8F%90%E7%A4%BA%E4%B8%8E%E8%BE%93%E5%87%BA%E4%B8%8A%E9%99%90%22%5D%20--%3E%20PSEL%5B%22%E9%80%89%20P%20%E5%AE%9E%E4%BE%8B%EF%BC%9A%E9%98%9F%E5%88%97%E4%B8%8E%E6%8F%90%E7%A4%BA%E9%95%BF%22%5D%0A%20%20PSEL%20--%3E%20PEXE%5B%22P%20%E6%B1%A0%EF%BC%9A%E5%88%86%E5%9D%97%E5%89%8D%E5%A1%AB%EF%BC%8C%E9%80%90%E5%B1%82%E4%BA%A7%20KV%22%5D%0A%20%20PEXE%20--%3E%20XFER%5B%22KV%20%E6%B5%81%E6%B0%B4%E4%BC%A0%E8%BE%93%EF%BC%9A%E4%B8%8E%E5%B0%BE%E6%AE%B5%E5%89%8D%E5%A1%AB%E9%87%8D%E5%8F%A0%22%5D%0A%20%20XFER%20--%3E%20DSEL%5B%22%E9%80%89%20D%20%E5%AE%9E%E4%BE%8B%EF%BC%9A%E4%BA%B2%E5%92%8C%E5%AE%9A%E5%AE%B6%22%5D%0A%20%20DSEL%20--%3E%20DEXE%5B%22D%20%E6%B1%A0%EF%BC%9Adecode%EF%BC%8C%E9%80%90%E6%AD%A5%E6%B5%81%E5%BC%8F%22%5D%0A%20%20DEXE%20--%3E%20BP%7B%22D%20%E6%B1%A0%E6%B0%B4%E4%BD%8D%E9%AB%98%22%7D%0A%20%20BP%20--%3E%7C%E6%98%AF%7C%20THRO%5B%22%E5%8F%8D%E5%8E%8B%EF%BC%9AP%20%E6%B1%A0%E9%99%8D%E9%80%9F%E6%88%96%E8%AF%B7%E6%B1%82%E6%8E%92%E9%98%9F%22%5D%0A%20%20BP%20--%3E%7C%E5%90%A6%7C%20DONE%5B%22%E7%BB%A7%E7%BB%AD%E7%94%9F%E6%88%90%E8%87%B3%E7%BB%93%E6%9D%9F%22%5D%0A%20%20THRO%20--%3E%20PSEL%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>本课的方法是<strong>服务时间核算加显式协议</strong>：两池配比的起点由稳态服务时间之比给出——每请求在两阶段的耗时比——再按双 SLO 与异构档位微调；公式管均值，突发靠实测修正。拆池后丢失的耦合用显式反压协议补回：D 池水位高则 P 池降速，替代 colocate 里隐式的预算争用。goodput 拆成两半记账（TTFT 归 P 池与传输、TPOT 归 D 池），各按各的承诺验收，是方法上的关键分账。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>两池的队列必须联动，反压是 PD 调度独有的机制：D 池水位高时，P 池降速或把新请求停在 P 侧门外——显式协议替代了 colocate 里隐式的预算争用。<span class="marginnote">直觉类比：反压就像前厨与出菜口之间的传菜铃——出菜口（D 池）堆了，铃一响，前厨（P 池）就放慢炒菜。合用一间厨房（colocate）时这层协调是隐性的（同一步抢预算）；拆成两间厨房后必须装上明确的传菜铃（协议），否则前厨只管猛炒，盘子在窗口堆到塌。</span>goodput 仍是目标函数，但分成两半记：TTFT 的账在 P 池与传输链路上，TPOT 的账在 D 池上，各按各的承诺验收。故障语义也变了：D 实例死掉，在途请求的 KV 随之丢失，恢复等于在另一个 D 上重做 prefill——上一课的代价账直接适用，这笔账也解释了为什么 D 侧亲和要把「家」固定得比 colocate 更稳。传输链路本身是共享资源：多对 P-D 同时搬 KV 会撞带宽，传输也要排队；按层切传输，正好把一次搬运摊进多个迭代。</p><p>KV 传输的时机为什么讲究，送早、送晚、对齐三种情形：</p>',5)),(e(),o(A,null,{default:a(()=>[l(B,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20EARLY%5B%22%E9%80%81%E6%97%A9%E4%BA%86%22%5D%0A%20%20%20%20E1%5B%22P%20%E8%BE%B9%E7%AE%97%E8%BE%B9%E5%BE%80%20D%20%E9%80%81%20KV%22%5D%20--%3E%20E2%5B%22D%20%E7%9A%84%E6%98%BE%E5%AD%98%E8%A2%AB%E5%9C%A8%E9%80%94%20KV%20%E5%8D%A0%E4%BD%8F%22%5D%0A%20%20%20%20E2%20--%3E%20E3%5B%22decode%20%E5%B9%B6%E5%8F%91%E8%A2%AB%E6%8C%A4%E5%B0%8F%22%5D%0A%20%20end%0A%20%20subgraph%20LATE%5B%22%E9%80%81%E6%99%9A%E4%BA%86%22%5D%0A%20%20%20%20L1%5B%22%E9%A6%96%20token%20%E7%AE%97%E5%AE%8C%E6%89%8D%E5%BC%80%E5%A7%8B%E9%80%81%22%5D%20--%3E%20L2%5B%22D%20%E5%AE%9E%E4%BE%8B%E5%B9%B2%E7%AD%89%20KV%22%5D%0A%20%20%20%20L2%20--%3E%20L3%5B%22TTFT%20%E5%8F%98%E9%95%BF%EF%BC%8C%E7%AE%97%E5%8A%9B%E9%97%B2%E7%BD%AE%22%5D%0A%20%20end%0A%20%20subgraph%20ALIGNED%5B%22%E7%9B%AE%E6%A0%87%EF%BC%9A%E6%B5%81%E6%B0%B4%E5%AF%B9%E9%BD%90%22%5D%0A%20%20%20%20O1%5B%22%E5%88%86%E5%9D%97%E5%89%8D%E5%A1%AB%E4%B8%8E%E9%80%90%E5%B1%82%E4%BC%A0%E8%BE%93%E9%87%8D%E5%8F%A0%22%5D%20--%3E%20O2%5B%22%E9%A6%96%20token%20%E5%AE%8C%E6%88%90%20%3D%20KV%20%E5%B7%B2%E5%B0%B1%E4%BD%8D%22%5D%0A%20%20%20%20O2%20--%3E%20O3%5B%22D%20%E7%AB%8B%E5%8D%B3%E5%BC%80%E8%B7%91%22%5D%0A%20%20end%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=t('<p><span class="marginnote">配比小算例：提示均值 1k token、输出均值 0.5k；单卡 prefill 6k token/s、decode 合计 1.5k token/s。每请求 P 阶段约 0.17 s、D 阶段约 0.33 s，卡数比 \\(N_P:N_D\\approx 1:2\\)。输出越长的负载 D 侧越重——agent 流量的 PD 比与搜索流量完全不同，配比要按自己的负载实测。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>拆池不是无代价的：KV 体积正比于提示长与层数，弱互连上搬运时间可能吃掉分离省下的干扰；小流量场景两池都喂不满，colocate 加 chunked prefill 往往更划算——主干课已写清这条边界（<a href="/llm/pd-disaggregation">PD 分离</a>）。配比公式在突发下失真：提示与输出长度的联合分布决定瞬时配比，稳态公式只管均值。<span class="marginnote">常见误区：初学者容易把配比公式当成一次算好、长期不变的定值。它只管均值——促销时段提示集体变长、agent 流量输出动辄几千 token，瞬时配比全在漂；公式给的是起跑线，双 SLO 微调与实测修正才是日常功课。</span>PD 也不是二选一：一部分卡混批、一部分拆池的混合形态在大机群上常见，代价是调度器要同时维护两套机制。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>拆池后调度新增四个决定：P 路由、D 亲和、传输时机、两池配比。</li><li>配比起点是服务时间比 \\((\\bar{p}/r_P):(\\bar{o}/r_D)\\)，再按双 SLO 微调。</li><li>反压是 PD 独有机制：D 满则 P 降速，替代 colocate 的隐式预算争用。</li><li>goodput 分两半记：TTFT 在 P 与传输，TPOT 在 D。</li><li>D 故障等于重 prefill，亲和要固定「家」；弱互连与小流量时拆池不划算。</li><li>出处：Zhong et al., OSDI 2024，arXiv:2401.09670；Patel et al., Splitwise, ISCA 2024，arXiv:2311.18677。</li></ul>',5))])}const m=D(n,[["render",d]]);export{T as __pageData,m as default};
